  steps = {
    { id = "h21-vallefresno-argenteos-001", ["do"] = "turnin", quest = 2458, npc = 7233, at = {1413, 55.44, 5.56}, z = 91.8, ["if"] = { class = {"ROGUE"} }, chain = "h21-vallefresno-argenteos-s001-7233", text = "Entrega «{quest:2458}» a {npc:7233}.", status = "unverified" },
    { id = "h21-vallefresno-argenteos-002", ["do"] = "accept", quest = 2478, npc = 7233, at = {1413, 55.44, 5.56}, z = 91.8, ["if"] = { class = {"ROGUE"} }, optional = true, chain = "h21-vallefresno-argenteos-s001-7233", text = "Coge «{quest:2478}» de {npc:7233}.", status = "unverified", reqlevel = 20 },
    { id = "h21-vallefresno-argenteos-003", ["do"] = "note", ["if"] = { class = {"ROGUE"} }, text = "«{quest:2478}» es para nivel 23 o más: los zánganos de la torre son de nivel 25 y Gallywix es élite de nivel 23. Hazla cuando puedas, en grupo.", status = "unverified" },
    { id = "h21-vallefresno-argenteos-004", ["do"] = "turnin", quest = 6541, npc = 8582, at = {1413, 48.12, 5.42}, z = 108.4, text = "Entrega «{quest:6541}» a {npc:8582}.", tip = "Desde el campamento de Seereth, dirígete al noreste a través de {map:1413} hasta el camino al norte del Cruce; los pícaros que vienen de la torre de Fizzule van hacia el oeste hasta él. {npc:8582} está en la torre de vigilancia de {area:1703}, donde el camino entra en {map:1440}.", status = "unverified" },
    { id = "h21-vallefresno-argenteos-005", ["do"] = "goto", at = {1440, 71.1, 68.1}, text = "Sigue el camino del norte hacia {area:431}.", status = "unverified" },
    { id = "h21-vallefresno-argenteos-006", ["do"] = "getfp", npc = 12616, at = {1440, 73.18, 61.59}, z = 103.9, node = "61", text = "Coge la ruta de vuelo de Puesto del Hachazo con {npc:12616}.", tip = "{area:431} está justo al norte, subiendo por el camino. Entrando desde el sur, primero están el maestro de vuelo y el tablón de caza de {npc:12696} en {area:428}, y luego los mercaderes. {npc:12867}, en el aserradero, ofrece «Avanzada de Vallefresno»: déjala para la próxima visita a {map:1440}, a nivel 26.", status = "unverified" },
    { id = "h21-vallefresno-argenteos-008", ["do"] = "turnin", quest = 6383, npc = 12696, at = {1440, 73.78, 61.46}, z = 101.9, chain = "h21-vallefresno-argenteos-s004-12696", text = "Entrega «{quest:6383}» a {npc:12696}.", status = "unverified" },
    { id = "h21-vallefresno-argenteos-009", ["do"] = "note", text = "Las presas de {npc:12696} (Ursangous, Shadumbra y Garrafilada) son para la próxima visita a {map:1440}, al 26.", status = "unverified" },
    { id = "h21-vallefresno-argenteos-010", ["do"] = "note", optional = true, text = "Vende lo que no sirve y repara con el vendedor.", status = "unverified" },
    { id = "h21-vallefresno-argenteos-011", ["do"] = "accept", quest = 98251, npc = 267214, at = {1440, 40.4, 61.5}, text = "Coge «{quest:98251}» de {npc:267214}.", status = "unverified", why = "+3.296 XP · ~17 min · desbloquea «{quest:98252}»", reqlevel = 18 },
