    { id = "h24-baldios-espolon-005", ["do"] = "goto", at = {1454, 45.3, 63.7}, ["if"] = { class = {"WARRIOR", "HUNTER", "ROGUE", "PRIEST", "SHAMAN", "MAGE", "WARLOCK", "DRUID"}, race = {"Orc", "Scourge", "Troll"} }, optional = true, text = "Ve al maestro de vuelo de {map:1454}.", tip = "Primero {map:1456}: dos de sus ancianos dan misiones que se hacen en los recorridos de esta guía y de la siguiente. Vuela a {area:378}; desde allí, camina al oeste hasta {map:1412} y al norte hasta las mesetas.", status = "unverified" },
    { id = "h24-baldios-espolon-006", ["do"] = "fly", zone = 1456, ["if"] = { class = {"WARRIOR", "HUNTER", "ROGUE", "PRIEST", "SHAMAN", "MAGE", "WARLOCK", "DRUID"}, race = {"Orc", "Scourge", "Troll"} }, optional = true, text = "Vuela a Campamento Taurajo.", status = "unverified" },
    { id = "h24-baldios-espolon-007", ["do"] = "goto", at = {1456, 47.0, 49.8}, ["if"] = { class = {"WARRIOR", "HUNTER", "ROGUE", "PRIEST", "SHAMAN", "MAGE", "WARLOCK", "DRUID"}, race = {"Orc", "Scourge", "Troll"} }, optional = true, text = "Ve a meseta central de {map:1456}.", tip = "Desde {area:378} sigue el camino al oeste y cruza la puerta hacia {map:1412}; luego al norte, pasando {area:222}, hasta {map:1456}; un elevador al pie de las mesetas te sube.", status = "unverified" },
    { id = "h24-baldios-espolon-008", ["do"] = "getfp", npc = 2995, at = {1456, 47.0, 49.83}, z = 177.0, node = "22", text = "Coge la ruta de vuelo de Cima del Trueno con {npc:2995}.", tip = "{npc:2995}, el maestro de jinetes del viento, está en la meseta central: consigue su ruta de vuelo si no la tienes. {npc:3024} y {npc:4721} están a poca distancia al este de él.", status = "unverified" },
