    { id = "h24-baldios-espolon-011", ["do"] = "fly", zone = 1413, text = "Vuela a El Cruce.", tip = "Vuela a El Cruce desde el maestro de jinetes del viento: {npc:2995}, en la meseta central de {map:1456}.", status = "unverified" },
    { id = "h24-baldios-espolon-012", ["do"] = "accept", quest = 1068, npc = 4049, at = {1413, 35.26, 27.88}, z = 14.3, optional = true, text = "Coge «{quest:1068}» de {npc:4049}, {npc:4074} y {npc:4073} deambulan al este de {npc:4201}, de camino arriba.", tip = "Sigue el camino al oeste pasando los búnkeres de Regthar: {npc:4049} acampa junto a él, en el límite de Sierra Espolón.", status = "unverified", reqlevel = 13 },
