    { id = "h24-baldios-espolon-014", ["do"] = "accept", quest = 1058, npc = 3995, at = {1442, 74.54, 97.94}, z = 17.2, optional = true, text = "Coge «{quest:1058}» de {npc:3995}.", tip = "Sigue el camino al oeste pasando los búnkeres de Regthar y el campamento de {npc:4049} hasta Sierra Espolón: {npc:3995} espera bajo tierra en {area:2539}, al pie de {area:1076}. +8.262 XP · ~68 min: por debajo de la media del tramo; hazla si te interesa la recompensa.", status = "unverified", reqlevel = 20 },
    { id = "h24-baldios-espolon-015", ["do"] = "complete", quest = 1068, obj = 2, at = {1442, 64.09, 56.62}, z = 6.1, wps = {{1442, 65.92, 55.39, "XT:9"}}, optional = true, text = "Mata {npc:4074} (1) para «{quest:1068}».", tip = "Sube por {area:1076} hasta la choza de {npc:4201}; luego al este por el camino hacia {area:461}: {npc:4074} patrulla el camino justo al este del cruce, y {npc:4073}, las laderas más al noreste bajo el risco. Ambos son robots machacadores solitarios; deambulan, así que sigue el camino hasta encontrarlos.", status = "unverified" },
    { id = "h24-baldios-espolon-016", ["do"] = "complete", quest = 1068, obj = 1, at = {1442, 67.2, 46.69}, optional = true, text = "Mata {npc:4073} (1) para «{quest:1068}».", status = "unverified" },
