    { id = "h24-baldios-espolon-041", ["do"] = "complete", quest = 6393, obj = 1, at = {1442, 37.34, 60.45}, z = 16.7, wps = {{1442, 34.7, 63.3, "Incendritas"}, {1442, 29.4, 65.6, "Incendritas"}, {1442, 31.7, 73.3, "Incendritas"}}, text = "Consigue {item:16312} (10) de {npc:4036} y {npc:4037} y {npc:4038} para «{quest:6393}».", tip = "Al suroeste del Refugio Roca del Sol está {area:465}, quemada. Planta las Semillas de Gaia en los túmulos de tierra del fondo del valle; los elementales de fuego sueltan {item:16312}. Las arpías Furia Sangrienta y las emboscadoras anidan en el lado norte; las destripadoras y las plumabribonas, al sur.", status = "unverified" },
