    { id = "h26-vallefresno-mil-agujas-021", ["do"] = "accept", quest = 6544, npc = 12858, at = {1440, 68.34, 75.3}, z = 107.9, escort = true, text = "Coge «{quest:6544}» de {npc:12858}.", tip = "Sigue al este por el camino. {npc:12858} espera al suroeste del Aserradero Grito de Guerra. Él y sus gruñones asaltan {area:2360}: deja que ellos atraigan a los enemigos y quédate con {npc:12858} hasta que muera {npc:12860}.", status = "unverified", why = "+2.400 XP · ~9 min", reqlevel = 20 },
    { id = "h26-vallefresno-mil-agujas-022", ["do"] = "complete", quest = 6544, escort = true, text = "Completa «{quest:6544}».", status = "unverified" },
    { id = "h26-vallefresno-mil-agujas-023", ["do"] = "accept", quest = 6503, npc = 12867, at = {1440, 71.11, 68.12}, z = 87.8, text = "Coge «{quest:6503}» de {npc:12867}.", tip = "Desde {area:2360}, ve al noreste hasta el Aserradero Grito de Guerra, junto al camino: allí está {npc:12867}.", status = "unverified", why = "+3.030 XP · ~7 min", reqlevel = 19 },
    { id = "h26-vallefresno-mil-agujas-024", ["do"] = "complete", quest = 6503, obj = 1, at = {1440, 72.5, 69.5}, z = 92.2, text = "Mata {npc:12856} (9) para «{quest:6503}».", tip = "Los elfos de la noche de «{quest:6503}» (23-24) acechan en los bosques al sur y al sureste del aserradero; usan sigilo, así que estate atento.", status = "unverified" },
    { id = "h26-vallefresno-mil-agujas-025", ["do"] = "loot", item = 16305, count = 1, at = {1440, 74.98, 70.06}, optional = true, text = "Consigue {item:16305} de {npc:12676}.", tip = "{npc:12676}, una gran sable de la noche, merodea por los mismos bosques más al este, de camino al norte hacia el Puesto del Hachazo. Su garra inicia la siguiente misión de caza.", status = "unverified" },
    { id = "h26-vallefresno-mil-agujas-026", ["do"] = "accept", quest = 2, optional = true, text = "Usa {item:16305} para empezar «{quest:2}».", status = "unverified", reqlevel = 20 },
