    { id = "h26-vallefresno-mil-agujas-105", ["do"] = "turnin", quest = 1196, npc = 4722, at = {1441, 46.14, 51.71}, z = 89.4, chain = "h26-vallefresno-mil-agujas-s054-4722", text = "Entrega «{quest:1196}» a {npc:4722}.", tip = "{npc:4722} está en {area:484}: el vial lleno de {npc:4721} es para él.", status = "unverified" },
    { id = "h26-vallefresno-mil-agujas-106", ["do"] = "accept", quest = 1197, npc = 4722, at = {1441, 46.14, 51.71}, z = 89.4, chain = "h26-vallefresno-mil-agujas-s054-4722", text = "Coge «{quest:1197}» de {npc:4722}, {obj:20807} en {area:1557}, entre los campamentos Galak.", status = "unverified", why = "+2.350 XP · ~1 min · 3,8× la mediana del 26-30", reqlevel = 20 },
    { id = "h26-vallefresno-mil-agujas-107", ["do"] = "complete", quest = 4821, obj = 1, at = {1441, 37.6, 56.1}, z = -64.0, text = "Recoge {item:12467} (1) de {obj:175565} para «{quest:4821}».", tip = "Baja en el elevador. El huevo está en un nido en el fondo del cañón, en uno de tres sitios: al sureste de las mesetas (52.3,55.2), al este (56.4,50.4) o al suroeste (37.6,56.1).", status = "unverified" },
    { id = "h26-vallefresno-mil-agujas-108", ["do"] = "complete", quest = 4841, obj = 1, at = {1441, 45.53, 43.54}, wps = {{1441, 45.7, 40.1, "Explorador Galak"}, {1441, 47.5, 41.6, "Explorador Galak"}, {1441, 43.2, 37.4, "Explorador Galak"}}, optional = true, text = "Mata {npc:4094} (12) para «{quest:4841}».", tip = "Los campamentos Galak llenan el cañón al norte del Poblado Viento Libre; exploradores, vaqueros y cazavientos comparten todos los campamentos. Un {npc:10617} solitario recorre un largo camino entre los campamentos: si te lo encuentras, mátalo; su nota inicia una misión para {area:2237}. No lo esperes.", status = "unverified" },
    { id = "h26-vallefresno-mil-agujas-109", ["do"] = "complete", quest = 4841, obj = 2, at = {1441, 46.13, 41.88}, wps = {{1441, 48.2, 40.9, "Vaquero Galak"}, {1441, 44.2, 40.0, "Vaquero Galak"}, {1441, 41.7, 37.6, "Vaquero Galak"}}, optional = true, text = "Mata {npc:4093} (10) para «{quest:4841}».", status = "unverified" },
    { id = "h26-vallefresno-mil-agujas-110", ["do"] = "complete", quest = 4841, obj = 3, at = {1441, 46.57, 41.16}, wps = {{1441, 44.8, 40.6, "Cazavientos Galak"}, {1441, 48.5, 41.1, "Cazavientos Galak"}, {1441, 43.7, 36.4, "Cazavientos Galak"}}, optional = true, text = "Mata {npc:4096} (6) para «{quest:4841}».", status = "unverified" },
    { id = "h26-vallefresno-mil-agujas-111", ["do"] = "loot", item = 12564, count = 1, at = {1441, 39.43, 33.1}, optional = true, text = "Consigue {item:12564} de {npc:10617}.", tip = "«{quest:4881}» de {npc:10617}, si te lo encuentras.", status = "unverified" },
    { id = "h26-vallefresno-mil-agujas-112", ["do"] = "accept", quest = 4881, optional = true, text = "Usa {item:12564} para empezar «{quest:4881}».", status = "unverified", reqlevel = 23 },
    { id = "h26-vallefresno-mil-agujas-113", ["do"] = "complete", quest = 1197, obj = 1, at = {1441, 42.0, 31.5}, z = -70.5, text = "Usa {item:5868} para «{quest:1197}».", tip = "A poca distancia al norte de los campamentos Galak, la cueva de {area:1557} baja hasta su cámara más profunda, donde arde {obj:20807}. Usa en él el {item:5868} y despoja enseguida la {item:5869}: la llama solo se apaga un momento, y si vuelve a encenderse pierdes el vial. Después ve al este, a la meseta de {npc:2986}.\nCuidado: dos guardias de llamas Galak (30) están junto al brasero y un guardia centauro recorre la cueva: atráelos de uno en uno antes de apagar la llama. {item:5868}, en {obj:20807}. Recoge {item:5869} (1) de {obj:20807} para «{quest:1197}». {item:5869}, de {obj:20807}.", status = "unverified" },
    { id = "h26-vallefresno-mil-agujas-114", ["do"] = "accept", quest = 1149, npc = 2986, at = {1441, 53.95, 41.49}, z = -6.9, text = "Coge «{quest:1149}» de {npc:2986}.", tip = "{npc:2986} está en lo alto de una meseta al este de los campamentos Galak. Para «{quest:1149}», salta desde el final de los tablones a su lado: aterrizarás sano y salvo.", status = "unverified", why = "+1.050 XP · ~2 min · desbloquea «{quest:1151}» y 1 más", reqlevel = 25 },
    { id = "h26-vallefresno-mil-agujas-115", ["do"] = "complete", quest = 1149, text = "Completa «{quest:1149}».", status = "unverified" },
