    { id = "h29-trabalomas-arathi-045", ["do"] = "complete", quest = 498, obj = 1, at = {1424, 75.33, 41.5}, z = 53.7, optional = true, text = "Usa {obj:1721} para «{quest:498}».", tip = "Al sureste del Molino Tarren. Drull y {npc:2238} están encadenados en los edificios del patio de la fortaleza: {npc:2427} lleva la {item:3467} y {npc:2428}, la {item:3499}, ambos dentro de la fortaleza. Mátalos y luego abre ambos candados. La bola y cadena de Drull.", status = "unverified" },
