    { id = "h29-trabalomas-arathi-076", ["do"] = "complete", quest = 553, obj = 3, at = {1424, 41.7, 6.4}, z = 145.0, text = "Usa {item:3710} para «{quest:553}».", tip = "La tercera llama arde en la cueva más pequeña, arriba en las colinas al norte de las cavernas.\nCuidado: Yetis gigantes y Yetis monteses (32-34) rodean la llama, a menudo en parejas, y Faucehielo, un yeti raro (37), deambula cerca. A nivel 30-31 están por encima de tu nivel: atrae a los yetis de uno en uno desde la boca de la cueva antes de usar la Vara, y localiza a Faucehielo antes de entrar.", status = "unverified" },
