    { id = "h29-trabalomas-arathi-090", ["do"] = "goto", at = {1424, 53.4, 48.8}, text = "Ve al norte del cementerio de Costasur.", tip = "Ve al este hasta el cementerio de {area:271}, en el borde noreste del pueblo: la tumba de Helcular está entre las demás. Llega desde el norte, bajando por la ladera que hay sobre el pueblo. Hay guardias de Costasur (55) en la esquina noroeste del cementerio y al sureste de la tumba: pasa entre ellos, entrega la misión y vete por donde viniste.", status = "unverified" },
