    { id = "h29-trabalomas-arathi-094", ["do"] = "accept", quest = 535, npc = 2333, at = {1416, 57.17, 69.51}, z = 151.2, optional = true, chain = "h29-trabalomas-arathi-s043-2333", text = "Coge «{quest:535}» de {npc:2333}.", tip = "Desde {area:271}, ve al norte pasando {area:272} y sigue el camino hasta las estribaciones de Alterac. «{quest:535}» espera junto al campamento del Sindicato. Solo ofrece su encargo mientras lleves «Infiltración» de {npc:2229}: dale la cerveza enseguida, y su recompensa es la Misiva de la Hermandad que quiere Krusk. Una misiva del Sindicato de aquí sirve igual: con una en tus bolsas, la guía se salta a «{quest:535}».", status = "unverified", reqlevel = 29 },
    { id = "h29-trabalomas-arathi-095", ["do"] = "turnin", quest = 535, npc = 2333, at = {1416, 57.17, 69.51}, z = 151.2, optional = true, chain = "h29-trabalomas-arathi-s043-2333", text = "Entrega «{quest:535}» a {npc:2333}.", status = "unverified" },
