    { id = "h32-mil-agujas-desolace-087", ["do"] = "accept", quest = 6161, at = {1443, 36.07, 30.41}, z = 2.1, text = "Coge «{quest:6161}» ({obj:177787}).", tip = "{obj:177787} está en el suelo justo al suroeste de la torre de {npc:11863}, de camino a la orilla: léelo. Sus dos llaves solo caen mientras tienes la misión.", status = "unverified", why = "+3.917 XP · ~6 min", reqlevel = 30 },
    { id = "h32-mil-agujas-desolace-088", ["do"] = "complete", quest = 6142, obj = 1, at = {1443, 30.6, 31.9}, z = -65.3, text = "Usa {obj:177784} para «{quest:6142}».", tip = "Ve al oeste hasta la orilla. Las almejas gigantes de concha blanda yacen en los bajíos y los reptadores de arrecife enfurecidos recorren la playa: cada almeja que abres en el fondo del mar, y algunos reptadores, dan una {item:15874}. Ábrela en tus bolsas para obtener su carne.\nLos reptadores y tenazas Pinzaseca de la misma playa llevan {item:15878}, aproximadamente uno de cada siete. Usa {item:15874} para «{quest:6142}». Consigue {item:15924} (10) de {npc:12347} para «{quest:6142}».", status = "unverified" },
    { id = "h32-mil-agujas-desolace-089", ["do"] = "complete", quest = 6161, obj = 1, at = {1443, 33.4, 30.1}, z = -23.4, text = "Consigue {item:15878} (1) para «{quest:6161}».", tip = "{item:15878}, de los cangrejos Pinzaseca.", status = "unverified" },
    { id = "h32-mil-agujas-desolace-090", ["do"] = "complete", quest = 6143, obj = 1, at = {1443, 32.18, 23.38}, z = 0.8, wps = {{1443, 31.4, 18.6, "Mirmidón Filozante"}, {1443, 33.9, 15.7, "Mirmidón Filozante"}, {1443, 29.7, 14.0, "Mirmidón Filozante"}}, text = "Mata {npc:4714} (7) para «{quest:6143}».", tip = "Sigue al norte hasta {area:598}. Los mirmidones, naga y hechiceras Filozante ocupan la playa; atráelos de uno en uno. Cualquier Filozante puede soltar {item:15881}.", status = "unverified" },
    { id = "h32-mil-agujas-desolace-091", ["do"] = "complete", quest = 6143, obj = 2, at = {1443, 32.74, 23.92}, z = -5.2, wps = {{1443, 36.0, 23.3, "Naga Filozante"}, {1443, 35.5, 27.2, "Naga Filozante"}, {1443, 36.7, 21.2, "Naga Filozante"}}, text = "Mata {npc:4711} (7) para «{quest:6143}».", status = "unverified" },
    { id = "h32-mil-agujas-desolace-092", ["do"] = "complete", quest = 6143, obj = 3, at = {1443, 32.94, 23.32}, z = -5.9, wps = {{1443, 32.0, 20.8, "Hechicera Filozante"}, {1443, 36.0, 26.8, "Hechicera Filozante"}, {1443, 39.0, 20.1, "Hechicera Filozante"}}, text = "Mata {npc:4712} (5) para «{quest:6143}».", status = "unverified" },
