    { id = "h32-mil-agujas-desolace-094", ["do"] = "complete", quest = 6027, obj = 1, at = {1443, 28.2, 6.7}, text = "Usa {item:15766} para «{quest:6027}».", tip = "Nada hasta {area:2406}, frente al extremo norte, y usa {item:15766} en Serpent Statue: aparece {npc:12369} (38); mátalo para obtener «{quest:6027}». Tiene bastante más nivel que tú: descansa hasta estar al máximo antes. {obj:177786} está en la orilla junto a la estatua: ábrelo con ambas llaves. {item:15766}, en Serpent Statue. Consigue {item:15803} (1) de {npc:12369} para «{quest:6027}».", status = "unverified" },
