    { id = "h34-tuercespina-041", ["do"] = "complete", quest = 575, obj = 1, at = {1434, 34.58, 10.46}, z = 14.6, wps = {{1434, 34.3, 9.0, "Piel de crocolisco de río grande"}, {1434, 38.5, 11.1, "Piel de crocolisco de río grande"}, {1434, 40.6, 13.6, "Piel de crocolisco de río grande"}}, text = "Consigue {item:4053} (2) de {npc:1150} para «{quest:575}».", tip = "Los crocoliscos fluviales están a lo largo del río, bajo el campamento. Los tigres de Tuercespina jóvenes merodean al oeste del campamento, y las panteras jóvenes al este. Ve hacia el oeste pasado el campamento. Los raptores de Tuercespina (33-34) cazan en los claros, y los trols Cabellesangre ocupan las ruinas de la costa: cualquier Cabellesangre puede soltar un colmillo. Un {item:4614} es un botín muy raro de ellos: si te sale uno, léelo. Cuidado: los campamentos trols tienen muchos enemigos patrullando, así que a menudo se unen otros trols al combate.", status = "unverified" },
