    { id = "h45-feralas-revolcafango-093", ["do"] = "complete", quest = 7003, obj = 1, at = {1444, 40.15, 38.65}, wps = {{1444, 38.0, 34.7, "Resíduo de reducción"}, {1444, 36.4, 36.1, "Resíduo de reducción"}, {1444, 34.5, 34.0, "Resíduo de reducción"}}, optional = true, text = "Consigue {item:18956} (15) para «{quest:7003}».", tip = "Usa {item:18904} para «{quest:7003}».", status = "unverified" },
    { id = "h45-feralas-revolcafango-094", ["do"] = "complete", quest = 3063, obj = 1, at = {1444, 37.81, 15.94}, z = 80.3, wps = {{1444, 40.3, 14.5, "Arpía Nortearroyo"}}, optional = true, text = "Mata {npc:5362} (4) para «{quest:3063}».", tip = "Las Arpías Nortearroyo anidan en las crestas del extremo noroeste. Son de nivel 48-50, unos niveles por encima de ti: las Clamavientos curan, así que mátalas primero y atráelas de una en una.", status = "unverified" },
    { id = "h45-feralas-revolcafango-095", ["do"] = "complete", quest = 3063, obj = 2, at = {1444, 37.44, 15.62}, z = 89.4, wps = {{1444, 38.6, 16.1, "Malapluma Nortearroyo"}, {1444, 38.2, 12.1, "Malapluma Nortearroyo"}, {1444, 39.7, 10.4, "Malapluma Nortearroyo"}}, optional = true, text = "Mata {npc:5363} (4) para «{quest:3063}».", status = "unverified" },
